$$
\boxed{
\begin{aligned}
&\text{先分别计算 triangle 和 bubble/contact 的 }1/\epsilon\text{ poles},
\\
&\text{再相消 physical }\widehat g^{\mu\nu}\text{ part},
\\
&\text{最后剩下 }
g_{(4)}^{\mu\nu}-\widehat g^{\mu\nu}
=
\widetilde g^{\mu\nu}.
\end{aligned}
}
$$

$$
\mathscr I^{AB}
\equiv
\nabla_-(X^AX^B)
=
\mathscr I_{(2)}^{AB}
+
g\mathscr I_{(3)}^{AB}
+
g^2\mathscr I_{(4)}^{AB}
+\cdots ,
$$

$$
\boxed{
\mathcal V_{\bar W}^{D;AC}
=
\frac{ig}{2}
f^{ACD}
\bar W^D_{\dot\alpha}
\left(
\bar D^{\dot\alpha(C)}
-
\bar D^{\dot\alpha(A)}
\right).
}
$$

$$
\boxed{
\begin{aligned}
\mathscr D_\triangle^{\dot\alpha}
={}&
\frac1{32}
\left[
D^2\bar D^2\delta^4(\theta)
\right]_{\theta=0}
\\
&\times
\left\{
-D_+,
\bar{\mathscr D}_{\bar W}^{\dot\beta}
\right\}
p_\gamma{}_{\dot\beta}
\left\{
\mathscr D_W^\gamma,
-\bar D^{\dot\alpha}
\right\}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\Gamma_{\triangle,3}^{A|B}
={}&
\frac{g^2}{2}
f^{ACD}f^{BCE}
\bar W^D_{\dot\alpha}(q)
p^\rho X^E(p)
\\
&\times
T_{\mu\rho\nu,+}{}^{\dot\alpha}
\int\frac{d^dk}{(2\pi)^d}
\frac{
L_1^\mu L_2^\nu
}{
D_0D_1D_2
}
\\
&+
\Gamma_{\triangle,\mathrm{coll}}
+
\Gamma_{\rm EOM}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\left[
\Gamma_{\triangle,3}^{A|B}
\right]_{\rm pole}
={}&
\frac{g^2}{32\pi^2\bar\epsilon}
f^{ACD}f^{BCE}
\\
&\times
\bar W^D_{\dot\alpha}
p^\rho X^E
T_{\mu\rho\nu,+}{}^{\dot\alpha}
\widehat g^{\mu\nu}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\Gamma_{\rm contact}^{A|B}
={}&
-\frac{g^2}{2}
f^{ACD}f^{BCE}
\bar W^D_{\dot\alpha}
p^\rho X^E
\\
&\times
T_{\mu\rho\nu,+}{}^{\dot\alpha}
g_{(4)}^{\mu\nu}
B_0(Q^2)
+
\Gamma_{\rm EOM},
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\left[
\Gamma_{\rm contact}^{A|B}
\right]_{\rm pole}
={}&
-\frac{g^2}{32\pi^2\bar\epsilon}
f^{ACD}f^{BCE}
\\
&\times
\bar W^D_{\dot\alpha}
p^\rho X^E
T_{\mu\rho\nu,+}{}^{\dot\alpha}
g_{(4)}^{\mu\nu}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\Gamma_{\triangle,3}
+
\Gamma_{\rm contact}
\Big|_{\rm local}
={}&
-\frac{g^2}{32\pi^2}
ff\,
T_{\mu\rho\nu}
\widetilde g^{\mu\nu}
\\
&\times
\left[
\frac1{\bar\epsilon}
+\text{finite scalar integrals}
\right].
\end{aligned}
}
$$

$$
\boxed{
\epsilon
\text{ 并不在 bare triangle numerator 中。}
}
$$

$$
\Gamma_{\rm contact}^{\rm local}
=
\frac{g^2}{16\pi^2}
ff\,
\left[
\frac1{\bar\epsilon}
+
F_{\rm contact}
\right]
\bar W_{\dot\alpha}p_+{}^{\dot\alpha}X.
$$

$$
\boxed{
\underbrace{
\Gamma_\triangle^{1/\epsilon}
}_{\text{ordinary UV divergent}}
+
\underbrace{
\Gamma_{\rm letter/bubble}^{1/\epsilon}
}_{\text{cancels physical pole}}
\quad\Longrightarrow\quad
\underbrace{
(g_{(4)}-\widehat g)\frac1\epsilon
}_{\text{finite chiral remainder}}.
}
$$

