}
$$

$$
\boxed{
\begin{aligned}
\mathcal T_1^{(2)}
={}&
\int_0^1ds\,
e^{s\mathbb d_w}
\mathbb A_w^{(2)}
e^{(1-s)\mathbb d_w}
\\
&+
\int_{0\le a\le b\le1}
da\,db\,
e^{a\mathbb d_w}
\mathbb A_w^{(1)}
e^{(b-a)\mathbb d_w}
\mathbb A_w^{(1)}
e^{(1-b)\mathbb d_w}.
\end{aligned}
}
$$

$$
\mathcal V_{\bar W}
=
\frac{ig}{2}
f^{ACD}\,
\bar W^D_{\dot\alpha}
\left(
\bar D_C^{\dot\alpha}
-
\bar D_A^{\dot\alpha}
\right),
$$

$$
\begin{aligned}
\Gamma_{T}^{A|B}(w)
={}&
\frac{g^2}{4}
f^{ACD}f^{BCE}
\int\frac{d^dk}{(2\pi)^d}
e^{iw\cdot r_2}
\\
&\times
\int d^4\theta_0d^4\theta_1d^4\theta_2\,
\bar W^D_{\dot\alpha}(\theta_1)
W_+^E(\theta_2)
\\
&\times
\Big[
D_{0-}^{[01]}K_{0+}^{[01]}K_{0+}^{[02]}
+
