\Big]
\\
&\times
\Big[
\bar D_1^{\dot\alpha[12]}
-
\bar D_1^{\dot\alpha[10]}
\Big]
\\
&\times
\Big[
D_{2\gamma}^{[21]}
-
D_{2\gamma}^{[20]}
\Big]
\\
&\times
\Pi_0\Pi_1\Pi_2 .
\end{aligned}
$$

$$
\begin{array}{c|c|c}
\bar D\text{ endpoint}
&
D\text{ endpoint}
&
\text{numerator}
\\ \hline
r_0&r_1&
(r_0)_{+\dot\beta}
p^{\dot\beta\gamma}
(r_1)_\gamma{}^{\dot\alpha}
\\
r_0&r_2&
(r_0)_{+\dot\beta}
p^{\dot\beta\gamma}
(r_2)_\gamma{}^{\dot\alpha}
\\
r_1&r_1&
(r_1)_{+\dot\beta}
p^{\dot\beta\gamma}
(r_1)_\gamma{}^{\dot\alpha}
\\
r_1&r_2&
(r_1)_{+\dot\beta}
p^{\dot\beta\gamma}
(r_2)_\gamma{}^{\dot\alpha}
\end{array}
$$

$$
\boxed{
\begin{aligned}
\Gamma_T^{A|B}(w)
={}&
\frac{g^2}{2}
f^{ACD}f^{BCE}
\bar W^D_{\dot\alpha}(q)
(ip^\rho)
X^E(p)
\\
&\times
T_{\mu\rho\nu,+}{}^{\dot\alpha}
\int\frac{d^dk}{(2\pi)^d}
\frac{
e^{iw\cdot r_2}
L_1^\mu L_2^\nu
}{
D_0D_1D_2
}
\\
&+
\Gamma_{\rm coll}
+
\Gamma_{\rm EOM}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\mathfrak N^{\mu\nu}(a,b)
\equiv{}&
\mu^{2\epsilon}
\int\frac{d^d\ell}{(2\pi)^d}
\frac{
e^{iw\cdot\ell}
(2\ell+A)^\mu(2\ell+B)^\nu
}
{(\ell^2+\Delta)^3}
\\[1mm]
={}&
\widehat g^{\mu\nu}J_2
\\
&+
\frac{i}{2}
\left(
w^\mu B^\nu
+
A^\mu w^\nu
\right)J_2
\\
&-
\frac12w^\mu w^\nu J_1
\\
&+
A^\mu B^\nu J_3.
\end{aligned}
}
$$

