\boxed{
iw\cdot(r-r')
\int_0^1ds\,
e^{isw\cdot r}
e^{i(1-s)w\cdot r'}
=
e^{iw\cdot r}
-
e^{iw\cdot r'}.
}
$$

$$
\boxed{
\begin{aligned}
\Gamma_{T,\rm pole}^{A|B}
={}&
\frac{g^2}{32\pi^2\bar\epsilon}
f^{ACD}f^{BCE}
\\
&\times
\mathcal K_w
\left[
\bar W^D_{\dot\alpha},
\,
p^\rho X^E
\right]
T_{\mu\rho\nu,+}{}^{\dot\alpha}
\widehat g^{\mu\nu}.
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\Gamma_{C,\rm pole}^{A|B}
={}&
-\frac{g^2}{32\pi^2\bar\epsilon}
f^{ACD}f^{BCE}
\\
&\times
\mathcal K_w
\left[
\bar W^D_{\dot\alpha},
\,
p^\rho X^E
\right]
T_{\mu\rho\nu,+}{}^{\dot\alpha}
g_{(4)}^{\mu\nu}.
\end{aligned}
}
$$

$$
\begin{aligned}
\Gamma_{T+C,\rm pole}^{A|B}
={}&
-\frac{g^2}{32\pi^2\bar\epsilon}
f^{ACD}f^{BCE}
\\
&\times
\mathcal K_w
\left[
\bar W^D_{\dot\alpha},
p^\rho X^E
\right]
T_{\mu\rho\nu,+}{}^{\dot\alpha}
\widetilde g^{\mu\nu}.
\end{aligned}
$$

$$
\boxed{
\begin{aligned}
\mathcal A_w^{AB}
={}&
\frac{g^2}{8\pi^2}
f^{ACD}f^{BCE}
\int_0^1db
\int_0^bda
\\
&\times
\Big[
(\mathcal T_a\bar W^D_{\dot\alpha})
\,
\mathcal T_b(\nabla_+{}^{\dot\alpha}X^E)
\\
&\hspace{15mm}
-
\mathcal T_a(\nabla_{+\dot\alpha}X^D)
\,
(\mathcal T_b\bar W^{E\dot\alpha})
\Big].
\end{aligned}
}
$$

$$
\boxed{
\begin{aligned}
\mathcal A_w^{AB}
={}&
\frac{g^2}{16\pi^2}
f^{ACD}f^{BCE}
\,
\mathcal K_w
\Big[
\bar W^D_{\dot\alpha},
\nabla_+{}^{\dot\alpha}X^E
\Big]
\\
&-
\frac{g^2}{16\pi^2}
f^{ACD}f^{BCE}
\,
\mathcal K_w
\Big[
\nabla_{+\dot\alpha}X^D,
\bar W^{E\dot\alpha}
\Big].
\end{aligned}
}
$$

$$
\begin{aligned}
\mathcal K_w[F,G]
&=
2\int_0^1db\int_0^bda\,
e^{a\mathbb D_w}F\,
e^{b\mathbb D_w}G
\\
&=
2
\sum_{m,n\ge0}
\frac{
(\mathbb D_w^mF)
(\mathbb D_w^nG)
}{
m!\,n!
}
\int_0^1db\int_0^bda\,
a^m b^n.
\end{aligned}
$$

