- ANOMALY_CANDIDATE_METRIC_POLE;
- ORDINARY_UV_POLE;
- W_LONGITUDINAL;
- LINK_WARD_CANCELLATION;
- COLLAPSED_CONTACT;
- EOM;
- CHIRAL_ZERO;
- NILPOTENT_ZERO;
- UV_FINITE_NONLOCAL;
- SCHEME_DEPENDENT_CONTACT;
- TADPOLE_SCALELESS;
- COUNTERTERM;
- UNCLASSIFIED.

